import { test, expect } from '@playwright/test'
import { mkdirSync } from 'node:fs'
import { join } from 'node:path'

/**
 * **Auto-trace** (TODO/sketch-004), driven against `/` — the running app.
 *
 * sketch-001's case 10, **Trace to scale**, end to end: load `e2e/fixtures/trace-bracket.jpg`
 * (generated by `scripts/generate-trace-fixtures.mjs`: 5 px per mm; an L-bracket 120 × 100 mm
 * with 30 mm arms whose outer corner is at image px (300, 150), two Ø 16 mm holes, and a ruler
 * whose 0 mark is at px (200, 915) and 100 mm mark at (700, 915)); Set scale along 100 mm of
 * the ruler; Auto-trace by tapping inside the bracket — 1 Solid + 2 Hole outlines; delete a
 * vertex and drag one; Linear 5 mm; Done — and the body is the bracket's true size within 1 mm.
 *
 * Real input throughout (`page.mouse`, trusted touch taps). Every viewport and every engine:
 * canvas, a worker decode and trace, WebGL, kernel results and persistence are all in play.
 */

const SNAPSHOT_DIR = join(process.cwd(), 'test-results', 'auto-trace-snapshots')
const BRACKET = join(process.cwd(), 'e2e', 'fixtures', 'trace-bracket.jpg')
const FOV_DEG = 45
const IMAGE = { widthPx: 1400, heightPx: 1000 }
const RULER_0 = [200, 915]
const RULER_100MM = [700, 915]
/** Where to tap: inside the bracket's top arm, clear of its holes. Moved to the sketch origin. */
const TAP_PX = [600, 240]
/** The L's inner corner, in image px. */
const INNER_CORNER_PX = [450, 300]
/** The bracket's true size, in mm, and its area less two Ø 16 holes. */
const BRACKET_MM = { width: 120, depth: 100, areaMm2: 120 * 30 + 30 * 70 - 2 * Math.PI * 8 * 8 }

/** @param {import('@playwright/test').TestInfo} info */
const isPhone = (info) => info.project.name.endsWith('-phone')
/** @param {import('@playwright/test').TestInfo} info */
const isLaptop = (info) => info.project.name.endsWith('-laptop')

/** @param {import('@playwright/test').Page} page */
async function openNewSketch(page) {
  const rows = page.getByTestId('library-rows')
  if (!(await rows.isVisible())) {
    await page.getByTestId('library-tab').click()
    await expect(rows).toBeVisible()
  }
  const row = await page.getByTestId('library-row-primitive.sketch').boundingBox()
  const view = await page.getByTestId('viewport').boundingBox()
  if (!row || !view) throw new Error('no Sketch row or viewport')
  await page.mouse.move(row.x + row.width / 2, row.y + row.height / 2)
  await page.mouse.down()
  await page.mouse.move(view.x + view.width / 2, view.y + view.height * 0.4 - 30, { steps: 8 })
  await page.mouse.move(view.x + view.width / 2, view.y + view.height * 0.4, { steps: 4 })
  await page.mouse.up()
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-sketch-mode', 'true')
}

/**
 * The sketch origin on screen and pixels per mm, while the editor looks straight down.
 *
 * @param {import('@playwright/test').Page} page
 */
async function sketchScreen(page) {
  const view = page.getByTestId('viewport')
  const box = await view.boundingBox()
  if (!box) throw new Error('no viewport')
  const distanceMm = Number(await view.getAttribute('data-camera-distance'))
  const mmPerPx = (2 * distanceMm * Math.tan((FOV_DEG * Math.PI) / 360)) / box.height
  return { x: box.x, y: box.y, cx: box.x + box.width / 2, cy: box.y + box.height / 2, pxPerMm: 1 / mmPerPx }
}

/**
 * A sketch mm point on screen.
 *
 * @param {import('@playwright/test').Page} page
 * @param {readonly number[]} mm
 */
async function mmOnScreen(page, mm) {
  const { cx, cy, pxPerMm } = await sketchScreen(page)
  return { x: cx + mm[0] * pxPerMm, y: cy - mm[1] * pxPerMm }
}

/**
 * An image pixel in sketch mm, for an unrotated photo at `mmPerPx` centred at `offsetMm`.
 *
 * @param {readonly number[]} px @param {number} mmPerPx @param {readonly number[]} offsetMm
 */
const pxToMm = (px, mmPerPx, offsetMm) => [offsetMm[0] + (px[0] - IMAGE.widthPx / 2) * mmPerPx, offsetMm[1] - (px[1] - IMAGE.heightPx / 2) * mmPerPx]

/** @param {import('@playwright/test').Page} page */
async function openSlices(page) {
  if ((await page.getByTestId('sketch-slices-panel').count()) === 0) await page.getByTestId('sketch-slices-toggle').click()
  await expect(page.getByTestId('sketch-slices-panel')).toBeVisible()
}

/**
 * @param {import('@playwright/test').Page} page
 * @param {{ x: number, y: number }} from
 * @param {{ x: number, y: number }} to
 */
async function mouseDrag(page, from, to) {
  await page.mouse.move(from.x, from.y)
  await page.mouse.down()
  await page.mouse.move((from.x + to.x) / 2, from.y + 2, { steps: 6 })
  await page.mouse.move(to.x, to.y, { steps: 6 })
  await page.mouse.up()
}

/** @param {import('@playwright/test').Page} page */
async function sceneBodies(page) {
  await page.waitForFunction(() =>
    [...document.querySelectorAll('[data-testid="scene-bodies"] li')].every((node) => node.hasAttribute('data-body-volume')),
  )
  return page.$$eval('[data-testid="scene-bodies"] li', (nodes) =>
    nodes.map((node) => ({
      bounds: (node.getAttribute('data-body-bounds') ?? '').split(',').map(Number),
      volume: Number(node.getAttribute('data-body-volume') ?? '0'),
    })),
  )
}

/**
 * The share of a 10 × 10 grid over the canvas that a tap would actually reach (ui-020 #3).
 *
 * @param {import('@playwright/test').Page} page
 */
function reachableCanvas(page) {
  return page.evaluate(() => {
    const canvas = document.querySelector('[data-testid="viewport-canvas"]')
    if (!canvas) throw new Error('no canvas')
    const box = canvas.getBoundingClientRect()
    let hits = 0
    for (let i = 0; i < 10; i += 1) {
      for (let j = 0; j < 10; j += 1) {
        if (document.elementFromPoint(box.left + (box.width * (i + 0.5)) / 10, box.top + (box.height * (j + 0.5)) / 10) === canvas) hits += 1
      }
    }
    return hits / 100
  })
}

/**
 * Load the bracket photo, Set scale along 100 mm of its ruler, and move the photo so the tap
 * point sits on the sketch origin — the X/Y offset fields a person uses to line a photo up.
 *
 * @param {import('@playwright/test').Page} page
 * @returns {Promise<{ mmPerPx: number, offsetMm: [number, number] }>}
 */
async function loadAndScale(page) {
  await openSlices(page)
  await page.getByTestId('sketch-image-input').setInputFiles(BRACKET)
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-reference-image', 'shown')
  await page.getByTestId('sketch-image-scale').click()
  await mouseDrag(page, await mmOnScreen(page, pxToMm(RULER_0, 0.1, [0, 0])), await mmOnScreen(page, pxToMm(RULER_100MM, 0.1, [0, 0])))
  await expect(page.getByTestId('sketch-scale-tool')).toHaveAttribute('data-step', 'length')
  await page.getByTestId('sketch-scale-length').fill('100')
  await page.getByTestId('sketch-scale-unit').selectOption('mm')
  await page.getByTestId('sketch-scale-apply').click()
  const badge = page.getByTestId('sketch-image-badge')
  await expect(badge).toHaveText(/^1 px = 0\.\d+ mm$/)
  const mmPerPx = Number(/= ([\d.]+) mm/.exec((await badge.textContent()) ?? '')?.[1])
  expect(Math.abs(mmPerPx / 0.2 - 1)).toBeLessThan(0.02)
  // Put the tap point on the origin.
  /** @type {[number, number]} */
  const offsetMm = [-(TAP_PX[0] - IMAGE.widthPx / 2) * mmPerPx, (TAP_PX[1] - IMAGE.heightPx / 2) * mmPerPx]
  for (const [axis, value] of /** @type {const} */ ([['x', offsetMm[0]], ['y', offsetMm[1]]])) {
    const field = page.getByTestId(`sketch-image-${axis}`)
    await field.fill(value.toFixed(3))
    await field.press('Enter')
  }
  // The field shows a rounded value; read back what the draft holds is not exposed, so use ours.
  return { mmPerPx, offsetMm }
}

test.beforeEach(async ({ page }) => {
  await page.goto('/')
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-webgl', 'ready')
})

test('trace to scale: Set scale, Auto-trace the bracket (1 Solid + 2 Holes), delete and drag a point, Linear 5 mm, Done — true size within 1 mm', async ({ page }, info) => {
  await openNewSketch(page)
  const { mmPerPx, offsetMm } = await loadAndScale(page)

  // Arm Auto-trace: the banner takes the toolbar's slot and the sheet gets out of the photo's way.
  await page.getByTestId('sketch-image-trace').click()
  const banner = page.getByTestId('sketch-trace-tool')
  await expect(banner).toBeVisible()
  await expect(page.getByTestId('sketch-trace-instruction')).toHaveText('Auto-trace: tap inside the part')
  await expect(page.getByTestId('sketch-toolbar')).toHaveCount(0)
  await expect(page.getByTestId('sketch-panel-sheet')).toHaveAttribute('data-collapsed', 'true')
  await expect(page.getByTestId('sketch-trace-finish')).toHaveText('Cancel')
  // The photo is calibrated, so there is no "not to scale" warning.
  await expect(page.getByTestId('sketch-trace-message')).toHaveCount(0)
  if (isPhone(info)) {
    // The sliders fold away on a narrow viewport; the photo stays tappable.
    await expect(page.getByTestId('sketch-trace-settings')).toHaveCount(0)
    expect(await reachableCanvas(page)).toBeGreaterThanOrEqual(0.69)
  }

  // Tap inside the bracket — on the origin, where its top arm now sits.
  const { cx, cy } = await sketchScreen(page)
  await page.mouse.click(cx, cy)
  const message = page.getByTestId('sketch-trace-message')
  await expect(message).toHaveText(/^Traced 1 outline and 2 holes — \d+ points$/, { timeout: 15000 })
  await expect(message).toHaveAttribute('data-kind', 'ok')
  await expect(banner).toHaveAttribute('data-state', 'idle')
  await expect(page.getByTestId('sketch-strokes')).toHaveAttribute('data-path-count', '3')
  await expect(page.locator('[data-testid^="sketch-profile-"][data-role="hole"]')).toHaveCount(2)
  await expect(page.locator('[data-testid^="sketch-profile-"][data-role="solid"]')).toHaveCount(1)
  mkdirSync(SNAPSHOT_DIR, { recursive: true })
  await page.screenshot({ path: join(SNAPSHOT_DIR, `${info.project.name}-traced.png`) })

  // Finish: Select is armed with the traced outline picked, its points showing.
  await expect(page.getByTestId('sketch-trace-finish')).toHaveText('Finish')
  await page.getByTestId('sketch-trace-finish').click()
  await expect(banner).toHaveCount(0)
  await expect(page.getByTestId('sketch-tool-select')).toHaveAttribute('aria-pressed', 'true')
  await expect(page.getByTestId('sketch-selection-status')).toContainText(/Closed outline, Solid — \d+ points/)
  const handles = page.getByTestId('sketch-vertex-handles')
  await expect(handles).toBeVisible()

  // The L's inner corner, in sketch mm — find the traced point there.
  const cornerMm = pxToMm(INNER_CORNER_PX, mmPerPx, offsetMm)
  const vertices = await page.locator('[data-testid^="sketch-vertex-"]').evaluateAll((nodes) =>
    nodes.map((node) => ({ id: node.getAttribute('data-testid') ?? '', x: Number(node.getAttribute('data-x-mm')), y: Number(node.getAttribute('data-y-mm')) })),
  )
  vertices.sort((a, b) => Math.hypot(a.x - cornerMm[0], a.y - cornerMm[1]) - Math.hypot(b.x - cornerMm[0], b.y - cornerMm[1]))
  const corner = vertices[0]
  expect(Math.hypot(corner.x - cornerMm[0], corner.y - cornerMm[1])).toBeLessThan(1) // traced within 1 mm
  const countBefore = vertices.length

  // Delete it: the corner is cut off by a diagonal.
  const cornerScreen = await mmOnScreen(page, [corner.x, corner.y])
  await page.mouse.click(cornerScreen.x, cornerScreen.y)
  await expect(page.getByTestId(corner.id)).toHaveAttribute('data-selected', 'true')
  await page.getByTestId('sketch-delete').click()
  await expect(page.locator('[data-testid^="sketch-vertex-"]')).toHaveCount(countBefore - 1)

  // Drag the diagonal's midpoint dot back onto the corner — the cut-off corner is restored. The
  // diagonal runs from the L's (900, 300) corner to its (450, 650) corner, so its dot is near
  // image px (675, 475).
  const box = await sketchScreen(page)
  const diagonal = await mmOnScreen(page, pxToMm([675, 475], mmPerPx, offsetMm))
  const mids = await page.locator('[data-testid^="sketch-midpoint-"]').evaluateAll((nodes) =>
    nodes.map((node) => ({ x: Number(node.getAttribute('cx')), y: Number(node.getAttribute('cy')) })),
  )
  mids.sort((a, b) => Math.hypot(box.x + a.x - diagonal.x, box.y + a.y - diagonal.y) - Math.hypot(box.x + b.x - diagonal.x, box.y + b.y - diagonal.y))
  expect(Math.hypot(box.x + mids[0].x - diagonal.x, box.y + mids[0].y - diagonal.y)).toBeLessThan(6)
  const mid = { x: box.x + mids[0].x, y: box.y + mids[0].y }
  await mouseDrag(page, mid, cornerScreen)
  await expect(page.locator('[data-testid^="sketch-vertex-"]')).toHaveCount(countBefore)

  // Linear, 5 mm, Done.
  if ((await page.getByTestId('sketch-extrude-panel').count()) === 0) await page.getByTestId('sketch-extrude-toggle').click()
  await page.getByTestId('sketch-method-linear').click()
  const height = page.getByTestId('sketch-param-heightMm')
  await height.fill('5')
  await height.press('Enter')
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-sketch-preview', 'ok')
  await page.getByTestId('sketch-done').click()
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-body-count', '1')

  // The bracket's true size, within 1 mm — and its holes are really there.
  const [body] = await sceneBodies(page)
  const [minX, minY, minZ, maxX, maxY, maxZ] = body.bounds
  expect(Math.abs(maxX - minX - BRACKET_MM.width)).toBeLessThan(1)
  expect(Math.abs(maxY - minY - BRACKET_MM.depth)).toBeLessThan(1)
  expect(maxZ - minZ).toBeCloseTo(5, 3)
  expect(Math.abs(body.volume / (BRACKET_MM.areaMm2 * 5) - 1)).toBeLessThan(0.03)
  await page.screenshot({ path: join(SNAPSHOT_DIR, `${info.project.name}-extruded.png`) })

  // It persists: save, reload, the same body.
  await expect(page.getByTestId('save-status')).toContainText('Saved', { timeout: 15000 })
  await page.reload()
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-body-count', '1')
  const [reloaded] = await sceneBodies(page)
  expect(reloaded.volume).toBeCloseTo(body.volume, 3)
})

test('touch only: Auto-trace by a finger tap on a phone, sliders folded, Finish is a 44 px target', async ({ page, browserName }, info) => {
  test.skip(!isPhone(info), 'phone touch pass')
  test.skip(browserName === 'firefox', 'Firefox has no touch emulation')
  await openNewSketch(page)
  await loadAndScale(page)
  await page.getByTestId('sketch-image-trace').tap()
  await expect(page.getByTestId('sketch-trace-tool')).toBeVisible()
  expect(await reachableCanvas(page)).toBeGreaterThanOrEqual(0.69)
  const finish = await page.getByTestId('sketch-trace-finish').boundingBox()
  expect(Math.min(finish?.width ?? 0, finish?.height ?? 0)).toBeGreaterThanOrEqual(43.5)
  const { cx, cy } = await sketchScreen(page)
  await page.touchscreen.tap(cx, cy)
  await expect(page.getByTestId('sketch-trace-message')).toHaveText(/^Traced 1 outline and 2 holes — \d+ points$/, { timeout: 15000 })
  await expect(page.getByTestId('sketch-strokes')).toHaveAttribute('data-path-count', '3')
  // Adjust opens the sliders; a coarser Tolerance re-traces the same tap with fewer points.
  const points = async () => Number(/— (\d+) points/.exec((await page.getByTestId('sketch-trace-message').textContent()) ?? '')?.[1])
  const before = await points()
  await page.getByTestId('sketch-trace-adjust').tap()
  await page.getByTestId('sketch-trace-tolerance').fill('3')
  await expect.poll(points).toBeLessThan(before)
  await expect(page.getByTestId('sketch-strokes')).toHaveAttribute('data-path-count', '3') // replaced, not added
  await page.screenshot({ path: join(SNAPSHOT_DIR, `${info.project.name}-touch-traced.png`) })
  await page.getByTestId('sketch-trace-finish').tap()
  await expect(page.getByTestId('sketch-trace-tool')).toHaveCount(0)
  await expect(page.getByTestId('sketch-toolbar')).toBeVisible()
})

test('desktop only: refusals say why; Threshold and Tolerance re-trace in place; Esc keeps the outlines; an unscaled photo says so', async ({ page }, info) => {
  test.skip(!isLaptop(info), 'keyboard and slider path')
  await openNewSketch(page)
  await openSlices(page)
  await page.getByTestId('sketch-image-input').setInputFiles(BRACKET)
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-reference-image', 'shown')
  await page.getByTestId('sketch-image-trace').click()
  // Not scaled yet: it says so before the first tap, and after it.
  const message = page.getByTestId('sketch-trace-message')
  await expect(message).toHaveText('Not to scale yet — outlines will use 1 px = 0.1 mm until you Set scale')
  await expect(message).toHaveAttribute('data-kind', 'warn')
  // The sliders are open where there is room.
  await expect(page.getByTestId('sketch-trace-settings')).toBeVisible()
  await expect(page.getByTestId('sketch-trace-tolerance-value')).toHaveText('0.5 mm')

  // A tap on the table: the region runs off the photo.
  const table = await mmOnScreen(page, pxToMm([1300, 100], 0.1, [0, 0]))
  await page.mouse.click(table.x, table.y)
  await expect(message).toHaveText('That region runs off the edge of the photo — tap inside the part')
  await expect(message).toHaveAttribute('data-kind', 'error')
  // A tap beside the photo altogether.
  const { x, y } = await sketchScreen(page)
  await page.mouse.click(x + 60, y + 400)
  await expect(message).toHaveText('Tap on the photo, inside the part')
  await expect(page.getByTestId('sketch-strokes')).toHaveAttribute('data-path-count', '0')

  // Inside the bracket's left arm.
  const arm = await mmOnScreen(page, pxToMm([375, 400], 0.1, [0, 0]))
  await page.mouse.click(arm.x, arm.y)
  await expect(message).toHaveText(/^Traced 1 outline and 2 holes — \d+ points\. Not to scale yet — Set scale, then answer Yes to resize them$/)
  await expect(page.getByTestId('sketch-trace-threshold-value')).toHaveText(/^Auto \(\d+\)$/)
  const points = async () => Number(/— (\d+) points/.exec((await message.textContent()) ?? '')?.[1])
  const fine = await points()
  await page.getByTestId('sketch-trace-tolerance').fill('3')
  await expect.poll(points).toBeLessThan(fine)
  await expect(page.getByTestId('sketch-strokes')).toHaveAttribute('data-path-count', '3')
  // A manual threshold: Auto off, the slider's value used.
  await page.getByTestId('sketch-trace-threshold-auto').click()
  await expect(page.getByTestId('sketch-trace-threshold-auto')).toHaveAttribute('aria-pressed', 'false')
  await page.getByTestId('sketch-trace-threshold').fill('60')
  await expect(page.getByTestId('sketch-trace-threshold-value')).toHaveText('60')
  await expect(message).toHaveText(/^Traced 1 outline/)
  await expect(page.getByTestId('sketch-strokes')).toHaveAttribute('data-path-count', '3')

  // Esc stands the tool down, keeping what it traced, with Select armed.
  await page.keyboard.press('Escape')
  await expect(page.getByTestId('sketch-trace-tool')).toHaveCount(0)
  await expect(page.getByTestId('sketch-tool-select')).toHaveAttribute('aria-pressed', 'true')
  await expect(page.getByTestId('sketch-strokes')).toHaveAttribute('data-path-count', '3')
  // Cancel on the editor throws the whole draft away, traced outlines included.
  await page.getByTestId('sketch-cancel').click()
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-body-count', '0')
})
